export type IContainer = {
	-- 容器标识
	Id: string,

	-- 获取父容器
	-- @return IContainer? 父容器
	getParent: (self: IContainer) -> IContainer?,

	-- 获取路径
	-- @return string 路径
	getPath: (self: IContainer) -> string,

	-- 是否包含子项
	-- @return boolean 是否包含子项
	getHasChildren: (self: IContainer) -> boolean,

	-- 获取指定标识的子项
	-- @param id 子项标识
	-- @return boolean 是否找到
	-- @return IContainer? 找到的子项
	tryGetChild: (self: IContainer, id: string) -> (boolean, IContainer?),

	-- 获取根容器
	-- @return IContainer 根容器
	getRootContainer: (self: IContainer) -> IContainer,

	-- 获取指定索引的子项
	-- @param index 索引
	-- @return boolean 是否找到
	-- @return IContainer? 找到的子项
	tryGetChildContainerByIndex: (self: IContainer, index: number) -> (boolean, IContainer?),

	-- 获取子项
	-- @param id 子项标识
	-- @return IContainer 子项
	getChild: (self: IContainer, id: string) -> IContainer,

	-- 获取子项列表
	-- @return { IContainer } 子项列表
	getChildren: (self: IContainer) -> { IContainer },

	-- 执行完行动后抛出事件
	-- @param actionName 行动名称
	-- @param args 行动参数
	onExecutedActionHandler: (actionName: string, args: { any? }) -> (),

	-- 查询数值变更后抛出事件
	-- @param queryName 查询名称
	-- @param value 查询值
	onQueryChangedEventHandler: (queryName: string, value: any) -> (),

	-- 分发查询变更事件
	-- @param queryName 查询名称
	-- @param value 查询值
	dispatchQueryChangedEvent: (self: IContainer, queryName: string, value: any) -> (),

	-- 执行完行动后调用
	-- @param actionName 行动名称
	-- @param args 行动参数
	onExecutedAction: (self: IContainer, actionName: string, args: { any? }) -> (),

	-- 清除已执行的动作处理器
	clearExecutedActionHandlers: (self: IContainer) -> (),
}
